package android.hardware.usb;import java.util.*;import android.app.PendingIntent;
public class UsbManager {public static final String ACTION_USB_DEVICE_DETACHED="usb.detached";public final HashMap<String,UsbDevice> devices=new HashMap<>();public volatile boolean permission=true,enumerationFailure;public UsbDeviceConnection connection=new UsbDeviceConnection();public PendingIntent requested;public int opens;public HashMap<String,UsbDevice> getDeviceList(){if(enumerationFailure)throw new IllegalStateException("USB service unavailable");return new HashMap<>(devices);}public boolean hasPermission(UsbDevice d){return permission;}public void requestPermission(UsbDevice d,PendingIntent p){requested=p;}public UsbDeviceConnection openDevice(UsbDevice d){opens++;return permission?connection:null;}}
